+func TestImageServerInfos(t *testing.T) {
+	server := config.ServerInfo{
+		ServerName: "host",
+		Type:       config.ServerTypePseudo,
+		Images: map[string]config.Image{
+			"second": {Name: "example/second", Digest: "sha256:abc"},
+			"first":  {Name: "example/first", Tag: "1.2"},
+		},
+	}
+	got := imageServerInfos(server)
+	if len(got) != 2 {
+		t.Fatalf("imageServerInfos() returned %d images, want 2", len(got))
+	}
+	for i, want := range []struct {
+		serverName string
+		image      config.Image
+	}{
+		{"0@host", server.Images["first"]},
+		{"1@host", server.Images["second"]},
+	} {
+		if got[i].ServerName != want.serverName || !reflect.DeepEqual(got[i].Image, want.image) || got[i].Type != "" {
+			t.Errorf("image %d = %+v, want name %q and image %+v", i, got[i], want.serverName, want.image)
+		}
+	}
+}
